import { IsNotEmpty, IsOptional, IsString, MinLength } from 'class-validator';

export class CreateBranchDto {
  @IsString()
  @IsNotEmpty()
  @MinLength(2)
  name: string;

  // Generated by the server; any client value is ignored.
  @IsOptional()
  @IsString()
  @IsNotEmpty()
  @MinLength(2)
  code?: string;

  @IsOptional()
  @IsString()
  address?: string;
}
